// Independent browser verification: generated files are copied, never changed.
import fs from 'node:fs';import path from 'node:path';import os from 'node:os';import http from 'node:http';import {once} from 'node:events';import {createRequire} from 'node:module';import {spawnSync} from 'node:child_process';import {createHash} from 'node:crypto';import {cliEnvironment} from '../src/services/cli-hello.js';
const out='docs/verification/first-real-build-20261106',target=JSON.parse(fs.readFileSync(out+'/prepared-target.json','utf8')),temp=fs.mkdtempSync(path.join(os.tmpdir(),'devsquad-first-live-browser-')),files=['index.html','style.css','app.js','README.md','app.test.cjs'];for(const f of files)fs.copyFileSync(path.join(target.root,f),path.join(temp,f));const hashes=Object.fromEntries(files.map(f=>[f,createHash('sha256').update(fs.readFileSync(path.join(temp,f))).digest('hex')]));const env=cliEnvironment(),syntax=spawnSync(process.execPath,['--check','app.js'],{cwd:temp,env,encoding:'utf8',timeout:10000,windowsHide:true}),unit=spawnSync(process.execPath,['--test','--test-concurrency=1','app.test.cjs'],{cwd:temp,env,encoding:'utf8',timeout:15000,windowsHide:true});fs.writeFileSync(out+'/generated-tests.txt',unit.stdout+unit.stderr);const checks=[],errors=[],blocked=[],require=createRequire(import.meta.url),{chromium}=require(path.join(process.env.USERPROFILE,'.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright'));const check=(name,pass)=>{checks.push({name,pass:!!pass});if(!pass)throw Error(name);};let server,browser;
try{check('Generated JavaScript syntax passes',syntax.status===0);check('Builder-authored tests executed separately and pass',unit.status===0&&/(?:#|ℹ)\s*pass\s+3\b/.test(unit.stdout));server=http.createServer((req,res)=>{const f={'/':'index.html','/index.html':'index.html','/style.css':'style.css','/app.js':'app.js'}[req.url];if(!f){res.writeHead(404).end();return;}res.setHeader('Content-Type',f.endsWith('.js')?'text/javascript':f.endsWith('.css')?'text/css':'text/html');res.setHeader('Content-Security-Policy',"default-src 'self'; connect-src 'none'; object-src 'none'; base-uri 'none'");res.end(fs.readFileSync(path.join(temp,f)));});server.listen(0,'127.0.0.1');await once(server,'listening');const base='http://127.0.0.1:'+server.address().port;browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,env});const context=await browser.newContext({viewport:{width:1366,height:768}});await context.route('**/*',r=>new URL(r.request().url()).origin===base?r.continue():(blocked.push('External request blocked'),r.abort()));const p=await context.newPage();p.on('pageerror',e=>errors.push(e.message));await p.goto(base);check('Application loads',await p.getByRole('heading',{name:'Everyday To-Do'}).isVisible());const input=p.getByLabel('New task',{exact:true}),add=p.getByRole('button',{name:'Add task',exact:true});check('Initial remaining count is zero',await p.locator('#remaining').textContent()==='0 tasks remaining');await input.fill('Buy milk');await add.click();await input.fill('Walk outside');await add.click();check('Two tasks are added and displayed',await p.locator('#task-list li').count()===2&&(await p.locator('#task-list').innerText()).includes('Buy milk'));check('Remaining count tracks additions',await p.locator('#remaining').textContent()==='2 tasks remaining');await p.getByRole('checkbox').first().check();check('Task can be completed',await p.locator('#task-list li').first().getAttribute('class')==='completed');check('Completion updates remaining count',await p.locator('#remaining').textContent()==='1 task remaining');await p.getByRole('checkbox').first().uncheck();check('Completed task can be reopened',await p.locator('#remaining').textContent()==='2 tasks remaining');await p.getByRole('button',{name:'Delete task: Walk outside',exact:true}).click();check('Task can be deleted and count updates',await p.locator('#task-list li').count()===1&&await p.locator('#remaining').textContent()==='1 task remaining');await p.reload();check('Tasks persist after refresh',await p.locator('#task-list li').count()===1&&(await p.locator('#task-list').innerText()).includes('Buy milk'));await p.getByRole('checkbox').first().check();await p.reload();check('Completion state persists after refresh',await p.getByRole('checkbox').first().isChecked()&&await p.locator('#remaining').textContent()==='0 tasks remaining');await input.fill('   ');await add.click();check('Whitespace-only task is rejected',await p.locator('#task-list li').count()===1);await input.fill('<img src=x onerror=alert(1)>');await add.click();check('Task markup remains literal text',await p.locator('#task-list img').count()===0&&(await p.locator('#task-list').innerText()).includes('<img'));await p.screenshot({path:out+'/todo-desktop.png'});await p.setViewportSize({width:390,height:844});check('Narrow viewport has no horizontal overflow',await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await p.screenshot({path:out+'/todo-mobile.png'});await p.evaluate(()=>localStorage.setItem('everyday-todo-v1','invalid-json'));await p.reload();check('Invalid saved data shows recovery warning and keeps app usable',(await p.locator('#storage-message').textContent()).includes('could not be loaded')&&await p.locator('#task-list li').count()===0);await input.fill('Recover');await add.click();check('Can add after invalid saved data',await p.locator('#task-list li').count()===1);check('No JavaScript errors or external requests',errors.length===0&&blocked.length===0);check('Original generated files were not changed',files.every(f=>hashes[f]===createHash('sha256').update(fs.readFileSync(path.join(target.root,f))).digest('hex')));
}catch(e){fs.writeFileSync(out+'/browser-functional-error.json',JSON.stringify({message:e.message},null,2));process.exitCode=1;}finally{await browser?.close();if(server?.listening)await new Promise(r=>server.close(r));const result={checks,passed:checks.filter(c=>c.pass).length,failed:checks.filter(c=>!c.pass).length,errors,blocked,syntaxExit:syntax.status,builderAuthoredTestsExit:unit.status,independentMultiAgentTests:false,temp,hashes,modelRequests:0};fs.writeFileSync(out+'/browser-functional.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));}
